import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression

MAX_DRIVERS = 5

def design(feats):
    # Find features with strong association (p < 0.01)
    strong_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            continue  # Skip clinical features for now
        t_stat = feats.x[:, i].T @ feats.y / (np.std(feats.x[:, i]) * np.sqrt(np.mean(feats.y) * (1 - np.mean(feats.y))))
        p_val = 2 * (1 - stats.t.cdf(abs(t_stat), feats.n - 1))
        if p_val < 0.01:
            strong_features.append((fid, p_val, feats.types[i]))

    # Sort by p-value
    strong_features.sort(key=lambda x: x[1])

    # Group correlated features
    correlated_groups = []
    seen = set()
    corr_matrix = np.corrcoef(feats.x.T)

    for i, fid1 in enumerate(feats.ids):
        if fid1 in seen:
            continue
        group = [fid1]
        for j, fid2 in enumerate(feats.ids):
            if i != j and abs(corr_matrix[i,j]) >= 0.6 and fid2 not in seen:
                group.append(fid2)
                seen.add(fid2)
        if len(group) > 1:
            correlated_groups.append(group)
        seen.add(fid1)

    # Select top drivers from strong features
    drivers = []
    used = set()

    # Add top correlated groups
    for group in correlated_groups:
        if len(drivers) >= MAX_DRIVERS:
            break
        # Prefer expression over copy_number
        best_fid = min(group, key=lambda f: feats.types[feats.column(f)] == 'copy_number')
        if best_fid not in used:
            drivers.append(best_fid)
            used.add(best_fid)

    # Add remaining strong features
    for fid, _, _ in strong_features:
        if len(drivers) >= MAX_DRIVERS:
            break
        if fid not in used:
            drivers.append(fid)
            used.add(fid)

    # Build columns and products
    columns = [f for f in feats.ids if f in used]
    products = []
    loadings = {}

    # Add interaction terms for top correlated pairs
    for i, fid1 in enumerate(columns):
        for j, fid2 in enumerate(columns[i+1:], i+1):
            if abs(corr_matrix[feats.column(fid1), feats.column(fid2)]) >= 0.6:
                products.append((fid1, fid2))

    # Weighted score: use standardized coefficients from logistic regression
    if columns:
        model = LogisticRegression(penalty='l1', solver='liblinear', fit_intercept=False)
        X = feats.x[:, [feats.column(f) for f in columns]]
        model.fit(X, feats.y)
        for i, f in enumerate(columns):
            loadings[f] = abs(model.coef_[0][i])

    # Ensure we don't exceed MAX_DRIVERS
    drivers = drivers[:MAX_DRIVERS-1] if len(drivers) > MAX_DRIVERS-1 else drivers

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )

